  ('casa-eterna-la-explanada', 'Casa Eterna', null, 'general'::center_type, 'Antioquia', 'Medellín', 'Calle 23 Sur #3-133, sector La Explanada, vía Las Palmas', 6.269732, -75.60256, 'municipality'::location_precision, array['Agua', 'Arroz', 'Aceite', 'Granos', 'Alimentos enlatados', 'Leche', 'Panela', 'Harina', 'Alimentos listos para consumir', 'Colchonetas', 'Cobijas', 'Pañales', 'Artículos de aseo']::text[], '{}', array['Ropa', 'Medicamentos', 'Alimentos perecederos', 'Productos vencidos']::text[], 'Lunes a domingo, 2:00 p. m. – 6:00 p. m.', '2026-08-11'::date, null, null, null, null, 'Pieza gráfica ciudadana difundida en redes (sin entidad identificable)', null, '2026-08-11'::date, 'disputed'::verification_status, 'NO PUBLICADO. La pieza lo agrupa bajo «Otros municipios» sin decir cuál. «Calle 23 Sur» con la vía Las Palmas de por medio cae en la frontera entre Medellín y Envigado, y la nomenclatura sur del Valle de Aburrá se repite entre municipios. Se aplica el mismo criterio que con el punto de Casanare: municipio ambiguo no se publica. Resolver antes de activarlo.', null)
on conflict (slug) do update set
  name = excluded.name,
  organization = excluded.organization,
  type = excluded.type,
  department = excluded.department,
  municipality = excluded.municipality,
  address = excluded.address,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  location_precision = excluded.location_precision,
  accepted_items = excluded.accepted_items,
  urgent_needs = excluded.urgent_needs,
  rejected_items = excluded.rejected_items,
  schedule_text = excluded.schedule_text,
  starts_at = excluded.starts_at,
  ends_at = excluded.ends_at,
  phone = excluded.phone,
  whatsapp = excluded.whatsapp,
  email = excluded.email,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  source_published_at = excluded.source_published_at,
  -- El estado NO se pisa si un administrador ya moderó el registro desde el
  -- panel. Sin esta guarda, un centro marcado inactivo porque cerró volvería a
  -- publicarse como verificado en la siguiente ejecución del seed.
  verification_status = case
    when public.collection_centers.moderated_at is not null
      then public.collection_centers.verification_status
    else excluded.verification_status
  end,
  verification_notes = case
    when public.collection_centers.moderated_at is not null
      then public.collection_centers.verification_notes
    else excluded.verification_notes
  end,
  last_verified_at = case
    when public.collection_centers.moderated_at is not null
      then public.collection_centers.last_verified_at
    else excluded.last_verified_at
  end;
